do $$
declare bad text;
begin
  select string_agg(f.code, ', ') into bad from _fill_ch f join public.restaurants r on r.michelin_url = f.michelin_url and r.restaurant_code <> f.code;
  if bad is not null then raise exception 'CH: michelin_url used by another row: %', bad; end if;
  select string_agg(f.code, ', ') into bad from _fill_ch f join public.restaurants r on r.google_place_id = f.place_id and r.restaurant_code <> f.code;
  if bad is not null then raise exception 'CH: Place ID used by another row: %', bad; end if;
end $$;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_ch f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null;
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_ch f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_ch f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set google_place_id = f.place_id, updated_at = now() from _fill_ch f where r.restaurant_code = f.code and f.place_id is not null and r.google_place_id is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_ch f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- CH post-conditions: MICHELIN's live 2026 listing plus the KEPT rows
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'CH' and michelin_stars = 3;
  if n <> 4 then raise exception 'CH: expected 4 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'CH' and michelin_stars = 2;
  if n <> 27 then raise exception 'CH: expected 27 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'CH' and michelin_stars = 1;
  if n <> 103 then raise exception 'CH: expected 103 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'CH'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'CH: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'CH' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'CH: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'CH' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'CH: % restaurants have both a hotel link and a property_name', n; end if;
end $$;

